\begin{equation*}
p\cosh\alpha+D\sinh\alpha
    =p\alpha\sinh\alpha+D\alpha\cosh\alpha+D\sinh\alpha ,
\qquad \alpha=kh,
\end{equation*}
so that

\begin{equation*}
 D=p\Big[\,\alpha^{-1}-\tanh\alpha\,\Big] .
\end{equation*}
The basal traction

\begin{equation*}
\sigma_{xz}(h)=S_{0}\sin kx\iff
-\frac{\mu}{k}\Big[B''(h)+k^{2}B(h)\Big]=S_{0}
\end{equation*}
gives with the $B$ above

\begin{equation*}
B''(h)+k^{2}B(h)=2k\Big[(D+p\alpha)\cosh\alpha
     +D\alpha\sinh\alpha\Big],
\end{equation*}
i.e.

\begin{equation*}
-2\mu\Big[(D+p\alpha)\cosh\alpha+D\alpha\sinh\alpha\Big]=S_{0}.
\end{equation*}
With $D=p[\alpha^{-1}-\tanh\alpha]$

\begin{equation*}
(D+p\alpha)\cosh\alpha+D\alpha\sinh\alpha
      =p\,\frac{\alpha^{2}+\cosh^{2}\alpha}{\alpha\cosh\alpha},
\end{equation*}
so that

\begin{equation*}
-2\mu p\,\frac{\alpha^{2}+\cosh^{2}\alpha}
                 {\alpha\cosh\alpha}=S_{0} .
\end{equation*}
In the steady state $\dot e=0$, $p=-\rho ge_{s}/2\mu$,

\begin{equation*}
\rho g e_{s}\,\frac{\alpha^{2}+\cosh^{2}\alpha}{\alpha\cosh\alpha}
      =S_{0},
\end{equation*}
i.e. the viscously relaxed dynamic topography driven by the harmonic
basal traction $S_{0}\sin kx$ is

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\,
      F(\alpha),\qquad 
F(\alpha)=\frac{\alpha\cosh\alpha}{\alpha^{2}+\cosh^{2}\alpha},
\qquad \alpha=kh=\frac{2\pi h}{\lambda} ,
\end{equation*}
so that

\begin{equation*}
e_{s}\simeq\alpha\frac{S_{0}}{\rho g}
       =\frac{kh\,S_{0}}{\rho g}
       =\frac{2\pi h}{\lambda}\frac{S_{0}}{\rho g},
\qquad \alpha\ll1,
\end{equation*}
and $e_{s}\to0$ for $k\to0$ as required by $u_{x}=0$ at $x=0,\lambda/2$.
For $ \alpha\sim1$

\begin{equation*}
F(1)=\frac{\cosh1}{1+\cosh^{2}1}\simeq0.46,
\qquad e_{s}\simeq0.46\,\frac{S_{0}}{\rho g},
\end{equation*}
the familiar $S_{0}/\rho g$ scaling with an $O(1)$ geometrical factor.
Writing the restoring stress in the isostatic form
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$,
$e_{s}=\chi S_{0}/\Delta\rho g$,

\begin{equation*}
e_{s}= \frac{\Delta\rho}{\rho}\,
      F(\alpha)\,\frac{S_{0}}{\Delta\rho g},
\qquad 
\chi_{0}(\alpha)=\frac{\Delta\rho}{\rho}
      \frac{\alpha\cosh\alpha}{\alpha^{2}+\cosh^{2}\alpha}\;,
\end{equation*}
and with the usual identification $\rho\equiv\Delta\rho$ used for the
normal stress jump in the statement,

\[
\chi(\alpha)=\frac{\alpha\cosh\alpha}{\alpha^{2}+\cosh^{2}\alpha}
          =\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}\;,
\qquad e_{s}=\chi(kh)\frac{S_{0}}{\Delta\rho g},
\]

